static void wifi_notify_carrier(void)
{
  bool carrier;
  irqstate_t flags;

  flags = rspin_lock_irqsave(&g_bk7258_driver_lock);
  if (!g_wifi.initialized || g_wifi.carrier_notified == g_wifi.carrier)
    {
      rspin_unlock_irqrestore(&g_bk7258_driver_lock, flags);
